 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    runs = []

    # Find contiguous non-background stripes on the grid boundary.
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                runs.append(("h", r, lo, c))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                runs.append(("v", c, lo, r))

    bar_cells = set()
    for axis, fixed, lo, hi in runs:
        if axis == "h":
            bar_cells.update((fixed, c) for c in range(lo, hi))
        else:
            bar_cells.update((r, fixed) for r in range(lo, hi))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not runs or not markers:
        return out
    paint = Counter(color for _, _, color in markers).most_common(1)[0][0]
    n_rays = len(markers)

    def cast(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = paint
            r += dr
            c += dc

    for axis, fixed, lo, hi in runs:
        # The sparse marker pattern specifies how many stripe cells launch rays.
        # Use the right/lower end of each boundary stripe, as in the demos.
        active = range(max(lo, hi - n_rays), hi)
        if axis == "h":
            dr = 1 if fixed == 0 else -1
            for c in active:
                cast(fixed + dr, c, dr, 0)
        else:
            dc = 1 if fixed == 0 else -1
            for r in active:
                cast(r, fixed + dc, 0, dc)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
