def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    runs = {"h": {0: [], h - 1: []}, "v": {0: [], w - 1: []}}

    # Boundary stripes are contiguous non-background runs of one color.
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                runs["h"][r].append((lo, c, color))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                runs["v"][c].append((lo, r, color))

    bar_cells = set()
    for side in runs["h"].values():
        for lo, hi, _ in side:
            bar_cells.update((r, c) for r in (0, h - 1) if (lo, hi, _) in runs["h"][r] for c in range(lo, hi))
    for side in runs["v"].values():
        for lo, hi, _ in side:
            bar_cells.update((r, c) for c in (0, w - 1) if (lo, hi, _) in runs["v"][c] for r in range(lo, hi))

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bar_cells]
    if not markers:
        return out
    paint = Counter(color for _, _, color in markers).most_common(1)[0][0]

    def cast(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = paint
            r += dr
            c += dc

    def fire_opposite_runs(axis, near_runs, far_runs, near_fixed, far_fixed):
        # Markers lying on the coordinate span of one edge stripe select ray lanes.
        # Transfer their offsets within that stripe to its opposite-edge partner.
        for near, far in zip(near_runs, far_runs):
            lo, hi, _ = near
            flo, fhi, _ = far
            offsets = set()
            for r, c, _color in markers:
                pos = c if axis == "h" else r
                if lo <= pos < hi:
                    offsets.add(pos - lo)
            if not offsets:
                flo, fhi = far[0], far[1]
                for r, c, _color in markers:
                    pos = c if axis == "h" else r
                    if flo <= pos < fhi:
                        offsets.add(pos - flo)
            for off in offsets:
                if lo + off < hi:
                    if axis == "h":
                        dr = 1 if near_fixed == 0 else -1
                        cast(near_fixed + dr, lo + off, dr, 0)
                    else:
                        dc = 1 if near_fixed == 0 else -1
                        cast(lo + off, near_fixed + dc, 0, dc)
                if flo + off < fhi:
                    if axis == "h":
                        dr = 1 if far_fixed == 0 else -1
                        cast(far_fixed + dr, flo + off, dr, 0)
                    else:
                        dc = 1 if far_fixed == 0 else -1
                        cast(flo + off, far_fixed + dc, 0, dc)

    fire_opposite_runs("h", runs["h"][0], runs["h"][h - 1], 0, h - 1)
    fire_opposite_runs("v", runs["v"][0], runs["v"][w - 1], 0, w - 1)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
