 "content": "from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Find repeated non-background runs along each pair of opposite borders.
    edges = {"h": {0: [], h - 1: []}, "v": {0: [], w - 1: []}}
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                edges["h"][r].append((lo, c, color))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                edges["v"][c].append((lo, r, color))

    bars = set()
    for side in edges["h"].values():
        for lo, hi, _ in side:
            bars.update((r, c) for r in (0, h - 1) for c in range(lo, hi)
                        if any((a, b) == (lo, hi) for a, b, _color in edges["h"][r]))
    for side in edges["v"].values():
        for lo, hi, _ in side:
            bars.update((r, c) for c in (0, w - 1) for r in range(lo, hi)
                        if any((a, b) == (lo, hi) for a, b, _color in edges["v"][c]))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bars]
    if not markers:
        return out
    paint = Counter(color for _, _, color in markers).most_common(1)[0][0]

    def cast(r, c, dr, dc):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = paint
            r += dr
            c += dc

    # Markers that fall within a border stripe select an offset.  Matching
    # stripes on the opposite border use the same offset, and both launch
    # inward rays.  A ray recolors its first marker to 4 and stops there.
    for axis, (side_a, side_b) in (("h", (0, h - 1)), ("v", (0, w - 1))):
        b_by_key = defaultdict(list)
        for run in edges[axis][side_b]:
            b_by_key[(run[1] - run[0], run[2])].append(run)
        for a in edges[axis][side_a]:
            key = (a[1] - a[0], a[2])
            if not b_by_key[key]:
                continue
            b = b_by_key[key].pop(0)
            alo, ahi, _ = a
            blo, bhi, _ = b
            offsets = set()
            for r, c, _color in markers:
                pos = c if axis == "h" else r
                if alo <= pos < ahi:
                    offsets.add(pos - alo)
                if blo <= pos < bhi:
                    offsets.add(pos - blo)
            for off in offsets:
                if off >= ahi - alo or off >= bhi - blo:
                    continue
                da = 1 if side_a == 0 else -1
                db = 1 if side_b == 0 else -1
                if axis == "h":
                    cast(side_a + da, alo + off, da, 0)
                    cast(side_b + db, blo + off, db, 0)
                else:
                    cast(alo + off, side_a + da, 0, da)
                    cast(blo + off, side_b + db, 0, db)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin)), separators=(",", ":")))
