def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    edges = {"h": {0: [], h - 1: []}, "v": {0: [], w - 1: []}}

    # Find same-color non-background runs on each boundary.
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color, lo = grid[r][c], c
            while c < w and grid[r][c] == color:
                c += 1
            if c - lo >= 2:
                edges["h"][r].append((lo, c, color))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            color, lo = grid[r][c], r
            while r < h and grid[r][c] == color:
                r += 1
            if r - lo >= 2:
                edges["v"][c].append((lo, r, color))

    bars = set()
    for side, runs in edges["h"].items():
        bars.update((side, c) for lo, hi, _ in runs for c in range(lo, hi))
    for side, runs in edges["v"].items():
        bars.update((r, side) for lo, hi, _ in runs for r in range(lo, hi))
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and (r, c) not in bars]
    if not markers:
        return out

    def cast(r, c, dr, dc, paint):
        while 0 <= r < h and 0 <= c < w:
            value = grid[r][c]
            if value == paint:
                out[r][c] = 4
                return
            if value != bg:
                return
            out[r][c] = paint
            r += dr
            c += dc

    # Pair opposite boundary runs by length and trigger color. A sparse
    # marker inside either run supplies its offset and its ray color; that
    # offset launches inward from both corresponding boundary locations.
    for axis, (side_a, side_b) in (("h", (0, h - 1)), ("v", (0, w - 1))):
        b_by_key = defaultdict(list)
        for run in edges[axis][side_b]:
            b_by_key[(run[1] - run[0], run[2])].append(run)
        for a in edges[axis][side_a]:
            key = (a[1] - a[0], a[2])
            if not b_by_key[key]:
                continue
            b = b_by_key[key].pop(0)
            alo, ahi, _ = a
            blo, bhi, _ = b
            launches = set()
            for r, c, paint in markers:
                pos = c if axis == "h" else r
                if alo <= pos < ahi:
                    launches.add((pos - alo, paint))
                if blo <= pos < bhi:
                    launches.add((pos - blo, paint))
            for off, paint in launches:
                if off >= ahi - alo or off >= bhi - blo:
                    continue
                da = 1 if side_a == 0 else -1
                db = 1 if side_b == 0 else -1
                if axis == "h":
                    cast(side_a + da, alo + off, da, 0, paint)
                    cast(side_b + db, blo + off, db, 0, paint)
                else:
                    cast(alo + off, side_a + da, 0, da, paint)
                    cast(blo + off, side_b + db, 0, db, paint)
    return out


